// Serialized into the selected lesson tab. Does not mutate the editor or save a lesson.
export async function sharedRecordBridge(request){
 try{
  if(typeof request==='string')request=JSON.parse(request);const destination=request.destination;
  if(request.practiceConfirmed!==true||!Number.isSafeInteger(destination?.id)||destination.id<1||destination.url!=='https://levelbuilder-studio.code.org/lessons/'+destination.id+'/edit'||location.href!==destination.url)throw Error('Open the confirmed owned practice lesson.');
  const stable=v=>Array.isArray(v)?'['+v.map(stable).join(',')+']':v&&typeof v==='object'?'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}':JSON.stringify(v);
  const fingerprint=async v=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(stable(v))))].map(b=>b.toString(16).padStart(2,'0')).join('');
  const deadline=()=>{if(request.deadlineAt&&Date.now()>request.deadlineAt)throw Error('Shared-record operation expired before dispatch.');};
  const scope=doc=>{const script=doc.querySelector('script[data-lesson][data-unitforlesson]');if(!script)throw Error('The native lesson course scope is unavailable.');const saved=JSON.parse(script.getAttribute('data-lesson')),unit=JSON.parse(script.getAttribute('data-unitforlesson'));if(saved.id!==destination.id||!Number.isSafeInteger(unit?.courseVersionId)||unit.courseVersionId<1)throw Error('The lesson has no verified course version.');return {destination,courseVersionId:unit.courseVersionId,saved};};
  const current=scope(document),fresh=async()=>{deadline();const response=await fetch('/lessons/'+destination.id+'/edit',{credentials:'same-origin',redirect:'error',cache:'no-store'});if(!response.ok)throw Error('Could not read the saved course scope.');const value=scope(new DOMParser().parseFromString(await response.text(),'text/html'));if(value.courseVersionId!==current.courseVersionId)throw Error('The editor course scope is stale.');return value;};
  if(request.action==='context')return await fresh();
  const kind=request.kind||request.item?.kind;if(!['resources','vocabularies'].includes(kind))throw Error('Unsupported shared-record collection.');
  if(request.action==='search'){
   if(request.courseVersionId!==current.courseVersionId)throw Error('Shared-record course scope changed.');const query=request.query;if(typeof query!=='string'||query.trim().length<3||query.length>255)throw Error('Use a searchable name or word.');deadline();const response=await fetch('/'+kind+'/search?'+new URLSearchParams({query,limit:'40',courseVersionId:String(current.courseVersionId)}),{credentials:'same-origin',redirect:'error',cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw Error('Shared-record search failed.');const rows=await response.json();if(!Array.isArray(rows)||rows.length>=40)throw Error('Shared-record search is incomplete. Use a more specific name.');return rows;
  }
  if(request.action!=='create'||request.mode!=='explicit-approved-shared-create')throw Error('Shared-record edits and deletion are unavailable.');
  const review=request.review,copy=structuredClone(review);delete copy.id;
  if(review?.kind!=='shared-record-review'||review.schemaVersion!==1||Date.now()>review.expiresAt||await fingerprint(copy)!==review.id||request.approval?.approved!==true||request.approval.reviewId!==review.id||stable(review.destination)!==stable(destination)||review.courseVersionId!==current.courseVersionId||!review.items.some(item=>stable(item)===stable(request.item)&&item.action==='create'))throw Error('This shared-record request does not match its approval.');
  const context=await fresh();if(await fingerprint(context.saved)!==review.baselineDigest)throw Error('Saved lesson content changed before shared-record creation.');
  const value=request.item.intent,keys=kind==='resources'?['name','type','audience','url','downloadUrl','embeddabilityType','curriculumCategory','includeInPdf','assessment']:['word','definition','commonSenseMedia'];if(Object.keys(value).length!==keys.length||keys.some(k=>!Object.hasOwn(value,k)))throw Error('Unexpected shared-record fields.');
  const label=kind==='resources'?value.name:value.word;if(typeof label!=='string'||label.trim().length<3||label.length>255)throw Error('Invalid shared-record name.');
  if(kind==='resources'){let url;try{url=new URL(value.url);}catch{throw Error('Invalid resource link.');}if(typeof value.type!=='string'||!value.type.trim()||value.type.length>100||url.protocol!=='https:'||url.username||url.password||value.url.length>255||!['Student','Teacher','Verified Teacher'].includes(value.audience)||value.type==='Answer Key'&&value.audience==='Student'||value.downloadUrl!==''||value.embeddabilityType!=='embed_and_resource_dropdown'||value.curriculumCategory!==''||value.includeInPdf!==false||value.assessment!==false)throw Error('Resource fields differ from supported creation settings.');}
  else if(typeof value.definition!=='string'||!value.definition.trim()||value.definition.length>60000||typeof value.commonSenseMedia!=='boolean')throw Error('Invalid vocabulary fields.');
  const token=document.querySelector('meta[name="csrf-token"]')?.content;if(!token)throw Error('The native sign-in token is unavailable.');
  const body=kind==='resources'?new URLSearchParams(Object.fromEntries(Object.entries({...value,courseVersionId:current.courseVersionId}).map(([k,v])=>[k,String(v)]))).toString():JSON.stringify({...value,courseVersionId:current.courseVersionId});deadline();
  const response=await fetch('/'+kind,{method:'POST',credentials:'same-origin',redirect:'error',headers:{'Content-Type':kind==='resources'?'application/x-www-form-urlencoded;charset=UTF-8':'application/json;charset=UTF-8','X-CSRF-Token':token,'X-Requested-With':'XMLHttpRequest'},body});
  if(!response.ok)return {outcome:'rejected',httpStatus:response.status};return {outcome:'response-received',record:await response.json()};
 }catch(error){if(request?.transportErrors)return {nativeBridgeError:String(error.message)};throw error;}
}
